#include <iostream>
#include <sstream>

int main() {
    std::istringstream entrada{" 5\n"};
    char actual = '?';
    while (entrada.get(actual)) {
        if (actual == ' ') {
            std::cout << "ESPACE\n";
        } else if (actual == '\n') {
            std::cout << "SAUT\n";
        } else {
            std::cout << "CARACTERE:" << actual << "\n";
        }
    }
    return 0;
}

