#include <iostream>
#include <sstream>

int main() {
    std::istringstream entrada{"3+8"};
    char actual = '?';
    while (entrada.get(actual)) {
        if (actual >= '0' && actual <= '9') {
            const int valor = actual - '0';
            std::cout << "Valeur: " << valor << "\n";
        } else {
            std::cout << "Signe: " << actual << "\n";
        }
    }
    return 0;
}

#include <iostream>
#include <sstream>

int main() {
    std::istringstream entrada{"2\t* 9\n"};
    char actual = '?';
    int digitos = 0;
    int separadores = 0;
    int otros = 0;
    while (entrada.get(actual)) {
        if (actual >= '0' && actual <= '9') {
            ++digitos;
        } else if (actual == ' ' || actual == '\t' || actual == '\n') {
            ++separadores;
        } else {
            ++otros;
        }
    }
    std::cout << "Chiffres: " << digitos;
    std::cout << "\nSéparateurs: " << separadores;
    std::cout << "\nAutres: " << otros;
    return 0;
}

